-- Written by the template editor on every save. Two jobs: a diff that can be read
-- in a commit, and a backup the whole set can be restored from:
--   sqlite3 templates_mssql.sqlite < templates_mssql.sql
-- The database of record is templates_mssql.sqlite. Rows are ordered by key, so a
-- diff shows what changed and nothing else.
create table if not exists SqlTemplate (  ActionKey   text not null primary key,  Sql         text not null,  ParamTypes  text,  Rules       text,  TestBounds  text,  RecordType  text,  RecordDecl  text,  KeyField    text,  CallerScope text,  Filter      text,  OrderBy     text,  ReadGroups  integer,  WriteGroups integer);
delete from SqlTemplate;
insert into SqlTemplate (ActionKey, Sql, ParamTypes, RecordType, RecordDecl, KeyField, CallerScope, Filter, OrderBy, Rules, TestBounds, ReadGroups, WriteGroups) values ('GetProductGroups', 'select ProductGroup_ID as ID, GroupCode as Code, GroupName as Name from ProductGroup order by GroupCode;', '', '', '', '', '', '', '', '', '', 0, 0);
insert into SqlTemplate (ActionKey, Sql, ParamTypes, RecordType, RecordDecl, KeyField, CallerScope, Filter, OrderBy, Rules, TestBounds, ReadGroups, WriteGroups) values ('GetProductNames', 'select ProductName_ID as ID, Name, Description from ProductName order by Name;', '', '', '', '', '', '', '', '', '', 0, 0);
insert into SqlTemplate (ActionKey, Sql, ParamTypes, RecordType, RecordDecl, KeyField, CallerScope, Filter, OrderBy, Rules, TestBounds, ReadGroups, WriteGroups) values ('GetProductNamesLike', 'select ProductName_ID as ID, Name, Description from ProductName where Name like ? order by Name;', 'text', '', '', '', '', '', '', '', '', 0, 0);
insert into SqlTemplate (ActionKey, Sql, ParamTypes, RecordType, RecordDecl, KeyField, CallerScope, Filter, OrderBy, Rules, TestBounds, ReadGroups, WriteGroups) values ('GetProductsForName', 'select top 50 p.Product_ID as ID, p.PartNo as PartNo, n.Name as Name, p.ListPrice as ListPrice from Product p inner join ProductName n on n.ProductName_ID = p.ProductName_ID where p.ProductName_ID = ? order by p.PartNo;', 'int', '', '', '', '', '', '', '', '', 0, 0);
insert into SqlTemplate (ActionKey, Sql, ParamTypes, RecordType, RecordDecl, KeyField, CallerScope, Filter, OrderBy, Rules, TestBounds, ReadGroups, WriteGroups) values ('GetSuppliers', 'select Supplier_ID as ID, VendorNo as VendorNo, Name as Name, PostCode as PostCode, City as City from Supplier where Name is not null and Name <> '''' order by Name, City;', '', '', '', '', '', '', '', '', '', 0, 0);
insert into SqlTemplate (ActionKey, Sql, ParamTypes, RecordType, RecordDecl, KeyField, CallerScope, Filter, OrderBy, Rules, TestBounds, ReadGroups, WriteGroups) values ('GetUnitsPerProductName', 'select n.Name as Name, count(p.Product_ID) as Units, avg(p.ListPrice) as AvgPrice from Product p inner join ProductName n on n.ProductName_ID = p.ProductName_ID group by n.Name having count(p.Product_ID) >= ? order by Units desc;', 'int', '', '', '', '', '', '', '', '', 0, 0);
